"use strict";

// OpenClaw Hook：auto-provision-stranger（2026-07-02 教練親定，全自動版）
// 用途：任何陌生 Telegram 用戶第一次跟小龍蝦講話，自動幫他建立獨立
//       agent（workspace + session store + binding），不需要教練發現、
//       不需要教練通知，教練不用當監控者。
// 事件：message:preprocessed
// 設計：純事件觸發，零輪詢。容器的 restart policy 是 unless-stopped，
//       所以 hook 寫完新設定後直接讓目前的 gateway 進程結束，
//       Docker 會立刻自動重啟容器把新設定套用生效——不需要主機層
//       cron 每分鐘檢查，不需要任何背景輪詢。

const fs = require('fs');
const path = require('path');

const OPENCLAW_DIR = path.resolve(__dirname, '../../');
const CONFIG_PATH = path.join(OPENCLAW_DIR, 'openclaw.json');
const LOG_PATH = path.join(OPENCLAW_DIR, 'logs', 'auto-provision.log');
const COACH_ID = '6124913915';

function log(msg) {
  try {
    fs.mkdirSync(path.dirname(LOG_PATH), { recursive: true });
    fs.appendFileSync(LOG_PATH, `[${new Date().toISOString()}] ${msg}\n`);
  } catch (_) {}
}

function extractSenderInfo(event) {
  const c = (event && event.context) || {};
  if ((c.channel || c.provider) !== 'telegram' && c.surface !== 'telegram') {
    // 防禦性檢查：也接受從 sessionKey 判斷
  }
  let senderId = c.senderId ? String(c.senderId) : null;
  if (!senderId && typeof c.from === 'string') {
    const m = c.from.match(/telegram:(\d+)/);
    if (m) senderId = m[1];
  }
  const senderName = c.senderName || c.senderUsername || '';
  const channel = c.provider || c.surface || '';
  return { senderId, senderName, channel };
}

const handler = async (event) => {
  if (!event || typeof event !== 'object') return;
  if (event.type !== 'message' || event.action !== 'preprocessed') return;

  try {
    const { senderId, senderName, channel } = extractSenderInfo(event);
    if (!senderId || channel !== 'telegram') return;
    if (senderId === COACH_ID) return;

    const cfg = JSON.parse(fs.readFileSync(CONFIG_PATH, 'utf-8'));
    const bindings = cfg.bindings || [];
    const alreadyBound = bindings.some(
      (b) => b.match && b.match.peer && String(b.match.peer.id) === senderId
    );
    if (alreadyBound) return;

    // 陌生人，開始自動開通
    const agentId = `trial-${senderId}`;
    const wsDir = path.join(OPENCLAW_DIR, `workspace-trial-${senderId}`);
    const mainWs = path.join(OPENCLAW_DIR, 'workspace');

    fs.mkdirSync(wsDir, { recursive: true });
    for (const f of ['AGENTS.md', 'SOUL.md', 'IDENTITY.md', 'TOOLS.md']) {
      const src = path.join(mainWs, f);
      if (fs.existsSync(src)) fs.copyFileSync(src, path.join(wsDir, f));
    }
    fs.writeFileSync(path.join(wsDir, 'MEMORY.md'), '# Long-Term Memory\n');
    fs.writeFileSync(
      path.join(wsDir, 'USER.md'),
      `# 客戶檔案 - ${senderName || '未命名'}\n\n- Telegram ID: ${senderId}\n- 首次開通：${new Date().toISOString()}（自動開通）\n`
    );

    if (!cfg.agents.list) cfg.agents.list = [];
    cfg.agents.list.push({ id: agentId, workspace: `~/.openclaw/workspace-trial-${senderId}` });
    if (!cfg.bindings) cfg.bindings = [];
    cfg.bindings.push({
      agentId,
      match: { channel: 'telegram', peer: { kind: 'direct', id: senderId } },
    });

    // 備份 + 寫回設定
    const ts = new Date().toISOString().replace(/[:.]/g, '-');
    fs.copyFileSync(CONFIG_PATH, `${CONFIG_PATH}.bak-auto-provision-${ts}`);
    fs.writeFileSync(CONFIG_PATH, JSON.stringify(cfg, null, 2) + '\n');

    log(`AUTO-PROVISIONED: senderId=${senderId} name=${senderName} agentId=${agentId} -> 觸發重啟生效`);

    // 設定檔已安全寫入磁碟（同步 fs 呼叫，此刻已完成）。
    // 直接結束目前的 gateway 進程，讓 Docker (restart policy: unless-stopped)
    // 立即自動重啟容器套用新設定——事件觸發，零輪詢。
    setTimeout(() => process.exit(1), 500);
  } catch (e) {
    log(`ERROR: ${e.message}`);
  }
};

module.exports = handler;
module.exports.default = handler;

