"use strict";

// OpenClaw Hook：vps-onboard-approve
// 用途：教練對 VPS 版小龍蝦本人說「核准/開通/放行 [對象]」時，
//       小龍蝦自己在本機（VPS 容器內）完成核准 + 建立獨立空間，
//       完全不需要 SSH、不需要 Mac、不需要 Hermes 當中間人。
// 事件：message:preprocessed
// 安全：只回應教練本人（COACH_ID），核准與否的判斷權永遠在教練——
//       這支 hook 只負責「教練說核准之後」把技術步驟做完，不自行判斷誰該核准。
// 建立：2026-07-06（教練親口要求：VPS 小龍蝦要能自己開通，跟 Mac 無關）

const fs = require('fs');
const path = require('path');
const { execFileSync } = require('child_process');

const OPENCLAW_DIR = path.resolve(__dirname, '../../');
const CONFIG_PATH = path.join(OPENCLAW_DIR, 'openclaw.json');
const LOG_PATH = path.join(OPENCLAW_DIR, 'logs', 'vps-onboard-approve.log');
const COACH_ID = '6124913915';

function log(msg) {
  try {
    fs.mkdirSync(path.dirname(LOG_PATH), { recursive: true });
    fs.appendFileSync(LOG_PATH, `[${new Date().toISOString()}] ${msg}\n`);
  } catch (_) {}
}

function extractText(event) {
  const c = (event && event.context) || {};
  const cands = [
    event.text, c.text, c.content, c.prompt, c.input, c.transcript, c.userText, c.body,
    (c.message && (typeof c.message === 'string' ? c.message : (c.message.text || c.message.content))),
  ];
  for (const v of cands) if (typeof v === 'string' && v.trim()) return v;
  return '';
}

function extractSenderInfo(event) {
  const c = (event && event.context) || {};
  let senderId = c.senderId ? String(c.senderId) : null;
  if (!senderId && typeof c.from === 'string') {
    const m = c.from.match(/telegram:(\d+)/);
    if (m) senderId = m[1];
  }
  const channel = c.provider || c.surface || '';
  return { senderId, channel };
}

function inject(event, content) {
  if (!event.context) event.context = {};
  if (!event.context.inject) event.context.inject = [];
  event.context.inject.push({ role: 'system', content });
}

function provisionWorkspace(senderId, displayName) {
  const agentId = `trial-${senderId}`;
  const wsDir = path.join(OPENCLAW_DIR, `workspace-trial-${senderId}`);
  const mainWs = path.join(OPENCLAW_DIR, 'workspace');

  const cfg = JSON.parse(fs.readFileSync(CONFIG_PATH, 'utf-8'));
  const bindings = cfg.bindings || [];
  const alreadyBound = bindings.some(
    (b) => b.match && b.match.peer && String(b.match.peer.id) === senderId
  );
  if (alreadyBound) return { ok: false, reason: 'already_provisioned' };

  fs.mkdirSync(wsDir, { recursive: true });
  for (const f of ['AGENTS.md', 'SOUL.md', 'IDENTITY.md', 'TOOLS.md']) {
    const src = path.join(mainWs, f);
    if (fs.existsSync(src)) fs.copyFileSync(src, path.join(wsDir, f));
  }
  fs.writeFileSync(path.join(wsDir, 'MEMORY.md'), '# Long-Term Memory\n');
  fs.writeFileSync(
    path.join(wsDir, 'USER.md'),
    `# 客戶檔案 - ${displayName || '未命名'}\n\n- Telegram ID: ${senderId}\n- 核准開通：${new Date().toISOString()}（教練核准，VPS本機自動完成）\n`
  );

  if (!cfg.agents.list) cfg.agents.list = [];
  cfg.agents.list.push({ id: agentId, workspace: `~/.openclaw/workspace-trial-${senderId}` });
  if (!cfg.bindings) cfg.bindings = [];
  cfg.bindings.push({
    agentId,
    match: { channel: 'telegram', peer: { kind: 'direct', id: senderId } },
  });

  const ts = new Date().toISOString().replace(/[:.]/g, '-');
  fs.copyFileSync(CONFIG_PATH, `${CONFIG_PATH}.bak-vps-approve-${ts}`);
  fs.writeFileSync(CONFIG_PATH, JSON.stringify(cfg, null, 2) + '\n');

  return { ok: true, agentId };
}

const handler = async (event) => {
  if (!event || typeof event !== 'object') return;
  if (event.type !== 'message' || event.action !== 'preprocessed') return;

  try {
    const { senderId } = extractSenderInfo(event);
    if (!senderId || senderId !== COACH_ID) return; // 只回應教練本人下的指令

    const text = extractText(event);
    if (!text) return;

    const m = text.trim().match(/^(核准|開通|放行)\s*(.+)$/);
    if (!m) return;
    const target = m[2].trim();

    log(`TRIGGERED by coach: action=${m[1]} target=${target}`);

    let listRaw;
    try {
      listRaw = execFileSync('openclaw', ['pairing', 'list', 'telegram', '--json'], {
        encoding: 'utf-8',
        timeout: 15000,
      });
    } catch (e) {
      log(`ERROR pairing list: ${e.message}`);
      inject(event, `核准流程失敗：查詢待核准清單時發生錯誤（${e.message}）。請如實回報教練這個異常，不要假裝已經核准成功。`);
      return;
    }

    // openclaw CLI 可能在 JSON 前後夾雜 doctor/migration 提示文字，取最後一段合法 JSON
    const jsonMatch = listRaw.match(/\{[\s\S]*\}\s*$/);
    if (!jsonMatch) {
      log(`ERROR: pairing list output not parseable: ${listRaw.slice(-300)}`);
      inject(event, `核准流程失敗：無法解析待核准清單的輸出格式。請回報教練這個異常，需要人工檢查。`);
      return;
    }
    const data = JSON.parse(jsonMatch[0]);
    const requests = data.requests || [];

    if (requests.length === 0) {
      inject(event, `教練說「${m[1]}${target}」，但目前沒有任何待核准的配對請求（清單是空的）。請如實回報教練：查無此人在等待核准，請確認對方是否已經傳過訊息給小龍蝦。`);
      return;
    }

    const isNumeric = /^\d+$/.test(target);
    let matches = requests.filter((r) =>
      isNumeric
        ? String(r.senderId || r.id) === target
        : String(r.senderName || r.displayName || r.name || '').includes(target)
    );
    if (matches.length === 0 && requests.length === 1) matches = requests;

    if (matches.length === 0) {
      inject(event, `教練說「${m[1]}${target}」，但待核准清單（共 ${requests.length} 筆）裡找不到符合的人。請把清單內容念給教練聽，請他確認正確的名字或 ID：${JSON.stringify(requests).slice(0, 500)}`);
      return;
    }
    if (matches.length > 1) {
      inject(event, `教練說「${m[1]}${target}」，但符合的候選有 ${matches.length} 筆，無法自動判斷是哪一位。請把候選清單念給教練聽，請他明確指定 ID：${JSON.stringify(matches).slice(0, 500)}`);
      return;
    }

    const reqTarget = matches[0];
    const code = reqTarget.code || reqTarget.pairingCode;
    const targetSenderId = String(reqTarget.senderId || reqTarget.id);
    const targetName = reqTarget.senderName || reqTarget.displayName || reqTarget.name || '';

    if (!code) {
      inject(event, `找到符合的請求（${targetName}/${targetSenderId}），但抓不到配對碼(code)欄位，無法自動核准。請回報教練需要人工檢查：${JSON.stringify(reqTarget)}`);
      return;
    }

    try {
      execFileSync('openclaw', ['pairing', 'approve', 'telegram', code, '--notify'], {
        encoding: 'utf-8',
        timeout: 15000,
      });
    } catch (e) {
      log(`ERROR pairing approve: ${e.message}`);
      inject(event, `核准指令執行失敗（${e.message}）。請如實回報教練，不要假裝已經核准成功。`);
      return;
    }
    log(`APPROVED: senderId=${targetSenderId} name=${targetName} code=${code}`);

    const result = provisionWorkspace(targetSenderId, targetName);
    if (!result.ok) {
      log(`PROVISION SKIPPED: ${result.reason}`);
      inject(event, `已核准 ${targetName}(${targetSenderId})，但獨立空間先前已經建立過，這次不重複建立。請回報教練：核准完成，空間本來就有了。`);
      return;
    }

    log(`PROVISIONED: senderId=${targetSenderId} name=${targetName} agentId=${result.agentId} -> 觸發重啟生效`);
    inject(event, `已成功核准並開通 ${targetName}(${targetSenderId}) 的獨立空間（agentId=${result.agentId}）。系統即將自動重啟套用設定，請回報教練：核准＋開通已完成。`);

    setTimeout(() => process.exit(1), 800);
  } catch (e) {
    log(`ERROR: ${e.message}`);
  }
};

module.exports = handler;
module.exports.default = handler;

