    if (!senderId || senderId !== COACH_ID) return; // 只回應教練本人下的指令

    const text = extractText(event);
    if (!text) return;

    const m = text.trim().match(/^(核准|開通|放行)\s*(.+)$/);
    if (!m) return;
    const target = m[2].trim();

    log(`TRIGGERED by coach: action=${m[1]} target=${target}`);

    let listRaw;
