        : String(r.senderName || r.displayName || r.name || '').includes(target)
    );
    if (matches.length === 0 && requests.length === 1) matches = requests;

    if (matches.length === 0) {
      inject(event, `教練說「${m[1]}${target}」，但待核准清單（共 ${requests.length} 筆）裡找不到符合的人。請把清單內容念給教練聽，請他確認正確的名字或 ID：${JSON.stringify(requests).slice(0, 500)}`);
      return;
    }
    if (matches.length > 1) {
      inject(event, `教練說「${m[1]}${target}」，但符合的候選有 ${matches.length} 筆，無法自動判斷是哪一位。請把候選清單念給教練聽，請他明確指定 ID：${JSON.stringify(matches).slice(0, 500)}`);
      return;
    }

    const reqTarget = matches[0];
    const code = reqTarget.code || reqTarget.pairingCode;
    const targetSenderId = String(reqTarget.senderId || reqTarget.id);
    const targetName = reqTarget.senderName || reqTarget.displayName || reqTarget.name || '';

    if (!code) {
      inject(event, `找到符合的請求（${targetName}/${targetSenderId}），但抓不到配對碼(code)欄位，無法自動核准。請回報教練需要人工檢查：${JSON.stringify(reqTarget)}`);
      return;
    }

