      execFileSync('openclaw', ['pairing', 'approve', 'telegram', code, '--notify'], {
        encoding: 'utf-8',
        timeout: 15000,
      });
    } catch (e) {
      log(`ERROR pairing approve: ${e.message}`);
      inject(event, `核准指令執行失敗（${e.message}）。請如實回報教練，不要假裝已經核准成功。`);
      return;
    }
    log(`APPROVED: senderId=${targetSenderId} name=${targetName} code=${code}`);

    const result = provisionWorkspace(targetSenderId, targetName);
    if (!result.ok) {
      log(`PROVISION SKIPPED: ${result.reason}`);
      inject(event, `已核准 ${targetName}(${targetSenderId})，但獨立空間先前已經建立過，這次不重複建立。請回報教練：核准完成，空間本來就有了。`);
      return;
    }

    log(`PROVISIONED: senderId=${targetSenderId} name=${targetName} agentId=${result.agentId} -> 觸發重啟生效`);
    inject(event, `已成功核准並開通 ${targetName}(${targetSenderId}) 的獨立空間（agentId=${result.agentId}）。系統即將自動重啟套用設定，請回報教練：核准＋開通已完成。`);

    setTimeout(() => process.exit(1), 800);
  } catch (e) {
    log(`ERROR: ${e.message}`);
  }
};

